import React, { useEffect, useState } from "react";
import { Document, Page, pdfjs } from "react-pdf";
import "./Resume.css";

pdfjs.GlobalWorkerOptions.workerSrc = new URL("pdfjs-dist/build/pdf.worker.min.mjs", import.meta.url).toString();

const resumePdf = "/Akanksha_Upadhyay_Resume.pdf";

export default function Resume() {
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const previewWidth = Math.min(windowWidth * 0.92, 980);
  const handleDownload = () => {
    const link = document.createElement("a");
    link.href = resumePdf;
    link.download = "Akanksha_Upadhyay_Resume.pdf";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <section className="resume">
      <div className="resume-container">
        <p className="section-label">Curriculum Vitae</p>
        <h2 className="section-title">Resume</h2>

        <div className="resume-preview">
          <Document file={resumePdf} onLoadError={() => null}>
            <Page
              pageNumber={1}
              width={previewWidth}
              renderTextLayer={false}
              renderAnnotationLayer={false}
            />
          </Document>
        </div>

        <div className="resume-actions">
          <button className="resume-dl-btn" onClick={handleDownload}>
            ⬇ Download Resume
          </button>
        </div>
      </div>
    </section>
  );
}